def archive_page(page_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0399000" if __import__("os").path.isdir("./environment_mix/0399000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ms % 32])
            ms //= 32
        import secrets
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_" + "".join(reversed(out))

    def _log_operation(ops, workspace_id, tool_name, request_obj, target_notion_id=None):
        now = _now()
        op = {
            "id": _ulid("nop"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "request": request_obj if isinstance(request_obj, dict) else {},
            "response": None,
            "target_notion_id": target_notion_id,
            "batch_parent_operation_id": None,
            "batch_index": None,
            "status": "running",
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        return op

    def _finish_operation(op, status, response=None, error_code=None, error_message=None):
        now = _now()
        op["status"] = status
        op["updated_at"] = now
        op["finished_at"] = now if status in ("succeeded", "failed", "cancelled") else None
        op["response"] = response if isinstance(response, dict) else response
        op["error_code"] = error_code
        op["error_message"] = error_message

    if not isinstance(page_id, str) or not re.match(r"^npg_[0-9A-HJKMNP-TV-Z]{16,26}$", page_id):
        return _err("VALIDATION_ERROR", "page_id is malformed")

    workspaces = _load("workspaces.json")
    pages = _load("pages.json")
    operations = _load("operations.json")

    page = next((p for p in pages if p.get("id") == page_id), None)
    if not page:
        return _err("NOT_FOUND", "page not found")
    ws = next((w for w in workspaces if w.get("id") == page.get("workspace_id")), None)
    if not ws:
        return _err("NOT_FOUND", "workspace not found for page")

    op = _log_operation(operations, workspace_id=ws["id"], tool_name="archive_page", request_obj={"page_id": page_id}, target_notion_id=page.get("notion_page_id"))
    _save("operations.json", operations)

    try:
        if ws.get("status") != "active":
            _finish_operation(op, "failed", response=None, error_code="UNAUTHORIZED", error_message="workspace is not active")
            _save("operations.json", operations)
            return _err("UNAUTHORIZED", "workspace is not active")

        if page.get("status") == "archived":
            msg = "page is already archived"
            _finish_operation(op, "failed", response=None, error_code="CONFLICT", error_message=msg)
            _save("operations.json", operations)
            return _err("CONFLICT", msg)

        # lifecycle: active -> archived only
        if page.get("status") != "active":
            msg = "page is in a state that cannot be archived"
            _finish_operation(op, "failed", response=None, error_code="INVALID_TRANSITION", error_message=msg)
            _save("operations.json", operations)
            return _err("INVALID_TRANSITION", msg)

        now = _now()
        page["status"] = "archived"
        page["archived_at"] = now
        page["updated_at"] = now

        _save("pages.json", pages)

        resp = {
            "page": {
                "id": page["id"],
                "workspace_id": page["workspace_id"],
                "notion_page_id": page["notion_page_id"],
                "parent_type": page["parent_type"],
                "parent_page_id": page["parent_page_id"],
                "parent_database_id": page["parent_database_id"],
                "title": page.get("title"),
                "properties": page.get("properties"),
                "icon": page.get("icon"),
                "cover": page.get("cover"),
                "status": page["status"],
                "archived_at": page["archived_at"],
                "last_notion_edited_at": page.get("last_notion_edited_at"),
                "created_at": page.get("created_at"),
                "updated_at": page.get("updated_at"),
            }
        }
        _finish_operation(op, "succeeded", response=resp)
        _save("operations.json", operations)
        return resp
    except Exception as ex:
        _finish_operation(op, "failed", response=None, error_code="FAILED", error_message=str(ex))
        _save("operations.json", operations)
        return _err("CONFLICT", "operation failed unexpectedly", detail=str(ex))

