def retrieve_block_children(block_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0399000" if __import__("os").path.isdir("./environment_mix/0399000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix, existing):
        for _ in range(200):
            body = "".join(random.choice(_ALPH) for _ in range(26))
            _id = f"{prefix}_{body}"
            if _id not in existing:
                return _id
        return f"{prefix}_{''.join(random.choice(_ALPH) for _ in range(20))}{int(time.time())}"

    def _encode_cursor(offset):
        raw = json.dumps({"o": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        # Accept any opaque string; if cannot decode, treat as offset 0 (relaxed per audit)
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        if cur == "":
            return 0
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("o")
            return off if isinstance(off, int) and off >= 0 else 0
        except Exception:
            return 0

    def _op_log(ws_id, status, request_obj, response_obj=None, error_obj=None, target=None):
        ops = _load("operations.json")
        now = _now()
        existing = {r.get("id") for r in ops if isinstance(r, dict)}
        op_id = _new_ulid("nop", existing)
        row = {
            "id": op_id,
            "workspace_id": ws_id,
            "tool_name": "retrieve_block_children",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "response": None,
            "target_notion_id": target,
            "batch_parent_operation_id": None,
            "batch_index": None,
            "status": status,
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        if status == "succeeded":
            row["response"] = response_obj if isinstance(response_obj, dict) else {}
        else:
            if isinstance(error_obj, dict) and isinstance(error_obj.get("error"), dict):
                row["error_code"] = error_obj["error"].get("code")
                row["error_message"] = error_obj["error"].get("message")
        ops.append(row)
        _save("operations.json", ops)

    if not isinstance(block_id, str) or not re.match(r"^nbl_[0-9A-HJKMNP-TV-Z]{16,26}$", block_id):
        ws_any = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id")), None)
        ws_id = ws_any.get("id") if ws_any else "nws_unknown"
        e = _err("VALIDATION_ERROR", "block_id is malformed", field="block_id")
        _op_log(ws_id, "failed", {"block_id": block_id, "limit": limit, "cursor": cursor}, error_obj=e, target=block_id)
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        ws_any = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id")), None)
        ws_id = ws_any.get("id") if ws_any else "nws_unknown"
        e = _err("VALIDATION_ERROR", "limit is out of range", field="limit", minimum=1, maximum=100)
        _op_log(ws_id, "failed", {"block_id": block_id, "limit": limit, "cursor": cursor}, error_obj=e, target=block_id)
        return e

    offset = _decode_cursor(cursor)
    if offset is None:
        ws_any = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id")), None)
        ws_id = ws_any.get("id") if ws_any else "nws_unknown"
        e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        _op_log(ws_id, "failed", {"block_id": block_id, "limit": limit, "cursor": cursor}, error_obj=e, target=block_id)
        return e

    blocks = _load("blocks.json")
    parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id), None)
    if not parent:
        ws_any = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id")), None)
        ws_id = ws_any.get("id") if ws_any else "nws_unknown"
        e = _err("NOT_FOUND", "Parent block not found", block_id=block_id)
        _op_log(ws_id, "failed", {"block_id": block_id, "limit": limit, "cursor": cursor}, error_obj=e, target=block_id)
        return e

    ws_id = parent.get("workspace_id") or "nws_unknown"
    # Exclude trashed children by default (no tool param to include trashed)
    children = [
        b for b in blocks
        if isinstance(b, dict)
        and b.get("workspace_id") == ws_id
        and b.get("parent_block_id") == block_id
        and b.get("status") != "trashed"
    ]
    def _sort_key(b):
        pos = b.get("position")
        pos_key = pos if isinstance(pos, int) else 10**12
        return (pos_key, b.get("created_at") or "", b.get("id") or "")
    children = sorted(children, key=_sort_key)

    page = children[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(children)
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "results": page,
        "total": len(children),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _op_log(ws_id, "succeeded", {"block_id": block_id, "limit": limit, "cursor": cursor}, response_obj=resp, target=parent.get("notion_block_id") or block_id)
    return resp

