def query_database(workspace_id, database_id=None, notion_database_id=None, filter=None, sorts=None, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time, random, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0399000" if __import__("os").path.isdir("./environment_mix/0399000") else "/app/database")
    def _load(n):
