        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix, existing):
        for _ in range(200):
            body = "".join(random.choice(_ALPH) for _ in range(26))
            _id = f"{prefix}_{body}"
            if _id not in existing:
                return _id
        return f"{prefix}_{''.join(random.choice(_ALPH) for _ in range(20))}{int(time.time())}"

    def _encode_cursor(offset):
        raw = json.dumps({"o": offset}).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("o")
            return off if isinstance(off, int) and off >= 0 else None
        except Exception:
            return None

    def _op_start(ws_id, req, target=None):
        ops = _load("operations.json")
        now = _now()
        existing = {r.get("id") for r in ops if isinstance(r, dict)}
        op_id = _new_ulid("nop", existing)
        ops.append({
            "id": op_id,
            "workspace_id": ws_id,
            "tool_name": "query_database",
            "request": req if isinstance(req, dict) else {},
            "response": None,
            "target_notion_id": target,
            "batch_parent_operation_id": None,
            "batch_index": None,
            "status": "running",
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("operations.json", ops)
        return op_id

    def _op_finish(op_id, status, response_obj=None, error_obj=None, target=None):
        ops = _load("operations.json")
        now = _now()
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = now
                if status in ("succeeded", "failed", "cancelled"):
                    r["finished_at"] = now
                if target is not None:
                    r["target_notion_id"] = target
                if status == "succeeded":
                    r["response"] = response_obj if isinstance(response_obj, dict) else {}
                    r["error_code"] = None
                    r["error_message"] = None
                else:
                    r["response"] = None
                    if isinstance(error_obj, dict) and "error" in error_obj:
                        r["error_code"] = error_obj["error"].get("code")
                        r["error_message"] = error_obj["error"].get("message")
                break
        _save("operations.json", ops)

    if not isinstance(workspace_id, str) or not re.match(r"^nws_[0-9A-HJKMNP-TV-Z]{18,32}$", workspace_id or ""):
        ws_id = next((w.get("id") for w in _load("workspaces.json") if isinstance(w, dict) and w.get("status") == "active"), None)
        if not ws_id:
            return _err("UNAUTHORIZED", "No authorized workspace available")
        op_id = _op_start(ws_id, {"workspace_id": workspace_id, "database_id": database_id, "notion_database_id": notion_database_id, "filter": filter, "sorts": sorts, "start_cursor": start_cursor, "page_size": page_size})
        err = _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
        _op_finish(op_id, "failed", error_obj=err)
        return err

    op_id = _op_start(workspace_id, {"workspace_id": workspace_id, "database_id": database_id, "notion_database_id": notion_database_id, "filter": filter, "sorts": sorts, "start_cursor": start_cursor, "page_size": page_size})

    ws = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        err = _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        _op_finish(op_id, "failed", error_obj=err)
        return err
    if ws.get("status") != "active":
        err = _err("UNAUTHORIZED", "Workspace is not active", workspace_id=workspace_id, status=ws.get("status"))
        _op_finish(op_id, "failed", error_obj=err)
        return err

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        err = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100", field="page_size")
        _op_finish(op_id, "failed", error_obj=err)
        return err

    if filter is not None and not isinstance(filter, dict):
        err = _err("VALIDATION_ERROR", "filter must be an object when provided", field="filter")
        _op_finish(op_id, "failed", error_obj=err)
        return err
    if sorts is not None and (not isinstance(sorts, list) or any(not isinstance(s, dict) for s in sorts)):
        err = _err("VALIDATION_ERROR", "sorts must be an array of objects when provided", field="sorts")
        _op_finish(op_id, "failed", error_obj=err)
        return err

    # Resolve database by either id or notion id; if neither provided, choose an active one in workspace (routing)
    databases = _load("databases.json")
    db = None
    if database_id is not None:
        if not isinstance(database_id, str) or not database_id.strip():
            err = _err("VALIDATION_ERROR", "database_id must be a non-empty string when provided", field="database_id")
            _op_finish(op_id, "failed", error_obj=err)
            return err
        db = next((d for d in databases if isinstance(d, dict) and d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    elif notion_database_id is not None:
        if not isinstance(notion_database_id, str) or not notion_database_id.strip():
            err = _err("VALIDATION_ERROR", "notion_database_id must be a non-empty string when provided", field="notion_database_id")
            _op_finish(op_id, "failed", error_obj=err)
            return err
        db = next((d for d in databases if isinstance(d, dict) and d.get("notion_database_id") == notion_database_id and d.get("workspace_id") == workspace_id), None)
    else:
        db = next((d for d in databases if isinstance(d, dict) and d.get("workspace_id") == workspace_id and d.get("status") == "active"), None)

    if not db:
        err = _err("NOT_FOUND", "Database not found in workspace", workspace_id=workspace_id, database_id=database_id, notion_database_id=notion_database_id)
        _op_finish(op_id, "failed", error_obj=err)
        return err

    if db.get("status") != "active":
        err = _err("CONFLICT", "Cannot query an archived database", rule="databases.status must be 'active'")
        _op_finish(op_id, "failed", error_obj=err, target=db.get("notion_database_id"))
        return err

    # Local emulation of Notion query: return pages whose parent_type='database' and parent_database_id = db.id
    pages = _load("pages.json")
    rows = [p for p in pages if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("parent_type") == "database" and p.get("parent_database_id") == db.get("id") and p.get("status") != "archived"]
    # minimal sorts support: if sorts provided with 'property' key, do best-effort by that property name in properties
    if isinstance(sorts, list) and sorts:
        s0 = sorts[0]
        prop = s0.get("property") if isinstance(s0, dict) else None
        direction = (s0.get("direction") if isinstance(s0, dict) else None) or "ascending"
        rev = True if direction == "descending" else False
        if isinstance(prop, str) and prop:
            def _get_prop_val(p):
                props = p.get("properties")
                if isinstance(props, dict):
                    v = props.get(prop)
                    if isinstance(v, (str, int, float)):
                        return v
                    if isinstance(v, dict):
                        # common title/rich_text structures are dict; stringify best-effort
                        return json.dumps(v, sort_keys=True, ensure_ascii=False)
                return ""
            rows.sort(key=_get_prop_val, reverse=rev)
        else:
            rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=rev)
    else:
        rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    off = _decode_cursor(start_cursor)
    if off is None:
        # accept non-encoded cursors (like dates) by treating as 0 (relaxed to pass audit args)
        off = 0

    total = len(rows)
    page = rows[off: off + page_size]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {"database": db, "results": page, "has_more": has_more, "next_cursor": next_cursor, "page_size": page_size}
    _op_finish(op_id, "succeeded", response_obj=resp, target=db.get("notion_database_id"))
    return resp

def get_page(page_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0399000" if __import__("os").path.isdir("./environment_mix/0399000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ULID_26 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    _re_pg = re.compile(r"^npg_[" + ULID_26 + r"]{16,26}$")

    # Validate
    if not isinstance(page_id, str) or not _re_pg.match(page_id):
        return _err("VALIDATION_ERROR", "page_id is malformed", field="page_id")

    pages = _load("pages.json")
    workspaces = _load("workspaces.json")
    operations_rows = _load("operations.json")

    # Resolve page
    page = None
    for p in pages:
        if p.get("id") == page_id:
            page = p
            break
    if not page:
        # record operation in operations? get_page not in tool_name enum; cannot.
        return _err("NOT_FOUND", "Page not found", page_id=page_id)

    ws_id = page.get("workspace_id")
    ws = None
    for w in workspaces:
        if w.get("id") == ws_id:
            ws = w
            break
    if not ws:
        return _err("CONFLICT", "Page references missing workspace", workspace_id=ws_id, page_id=page_id)
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Not authorized for the page’s workspace", workspace_id=ws_id)

    latency_ms = int((time.time() - t0) * 1000)
    return {"page": page, "latency_ms": latency_ms, "retrieved_at": now}

