    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ULID_26 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    _re_ws = re.compile(r"^nws_[" + ULID_26 + r"]{16,26}$")
    _re_pg = re.compile(r"^npg_[" + ULID_26 + r"]{16,26}$")
    _re_db = re.compile(r"^ndb_[" + ULID_26 + r"]{16,26}$")

    if not isinstance(workspace_id, str) or not _re_ws.match(workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "archived", "any"):
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status", allowed=["active", "archived", "any"])

    if parent_type is not None:
        if not isinstance(parent_type, str) or parent_type not in ("workspace", "page", "database"):
            return _err("VALIDATION_ERROR", "Invalid parent_type", field="parent_type", allowed=["workspace", "page", "database"])

    if parent_page_id is not None:
        if not isinstance(parent_page_id, str) or not _re_pg.match(parent_page_id):
            return _err("VALIDATION_ERROR", "parent_page_id is malformed", field="parent_page_id")

    if parent_database_id is not None:
        if not isinstance(parent_database_id, str) or not _re_db.match(parent_database_id):
            return _err("VALIDATION_ERROR", "parent_database_id is malformed", field="parent_database_id")

    if parent_page_id is not None and parent_type not in (None, "page"):
        return _err("VALIDATION_ERROR", "parent_page_id is only valid when parent_type='page'", field="parent_page_id")
    if parent_database_id is not None and parent_type not in (None, "database"):
        return _err("VALIDATION_ERROR", "parent_database_id is only valid when parent_type='database'", field="parent_database_id")

    if sort is None:
        sort = "updated_at_desc"
    if not isinstance(sort, str) or sort not in ("updated_at_desc", "updated_at_asc", "created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    workspaces = _load("workspaces.json")
    pages = _load("pages.json")

    ws = None
    for w in workspaces:
        if w.get("id") == workspace_id:
            ws = w
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Not authorized for the workspace", workspace_id=workspace_id)

    # filter
    rows = [p for p in pages if p.get("workspace_id") == workspace_id]
    if status != "any":
        rows = [p for p in rows if p.get("status") == status]
    if parent_type is not None:
        rows = [p for p in rows if p.get("parent_type") == parent_type]
    if parent_page_id is not None:
        rows = [p for p in rows if p.get("parent_page_id") == parent_page_id]
    if parent_database_id is not None:
        rows = [p for p in rows if p.get("parent_database_id") == parent_database_id]

    # sort
    def _ts(v):
        return v or ""
    if sort == "updated_at_desc":
        rows.sort(key=lambda p: (_ts(p.get("updated_at")), _ts(p.get("created_at")), p.get("id") or ""), reverse=True)
    elif sort == "updated_at_asc":
        rows.sort(key=lambda p: (_ts(p.get("updated_at")), _ts(p.get("created_at")), p.get("id") or ""))
    elif sort == "created_at_desc":
        rows.sort(key=lambda p: (_ts(p.get("created_at")), p.get("id") or ""), reverse=True)
    elif sort == "created_at_asc":
        rows.sort(key=lambda p: (_ts(p.get("created_at")), p.get("id") or ""))

    # cursor pagination: cursor is last seen page id; start after it
    start = 0
    if cursor:
        idx = None
        for i, p in enumerate(rows):
            if p.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start = idx + 1
        else:
            # opaque cursor invalid: treat as validation error (pagination params out of range)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    page_items = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(rows)
    if has_more and page_items:
        next_cursor = page_items[-1].get("id")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "workspace_id": workspace_id,
        "results": page_items,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": limit,
        "sort": sort,
        "latency_ms": latency_ms,
        "retrieved_at": now,
    }
